#include <stdio.h>
#include <sys/resource.h>

int main() {
    struct rlimit rlim;
    if (getrlimit(RLIMIT_NPTS, &rlim) == 0) {
        printf("Soft limit: %llu\n", (unsigned long long)rlim.rlim_cur);
        printf("Hard limit: %llu\n", (unsigned long long)rlim.rlim_max);
    } else {
        printf("Error getting limit\n");
    }
    return 0;
}
